import React, { useState } from "react";
import all_product from '../Components/Assets/all_product.js';

// Dummy cart data, bisa diganti dengan state global/context
const initialCart = [
  { productId: 13, qty: 1 },
  { productId: 25, qty: 2 }
];

function Cart() {
  const [cart, setCart] = useState(initialCart);
  const cartItems = cart.map(item => {
    const product = all_product.find(p => p.id === item.productId);
    return { ...item, ...product };
  });
  const total = cartItems.reduce((sum, item) => sum + item.new_price * item.qty, 0);

  return (
    <div className="shop-category" style={{ maxWidth: 700, margin: '40px auto', background: '#fff', borderRadius: 12, boxShadow: '0 2px 8px rgba(0,0,0,0.08)', padding: 32 }}>
      <h2>Your Cart</h2>
      {cartItems.length === 0 ? (
        <p>Keranjang belanja kosong.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: 24 }}>
          <thead>
            <tr style={{ background: '#f5f5f5' }}>
              <th style={{ padding: 8, borderBottom: '1px solid #eee' }}>Produk</th>
              <th style={{ padding: 8, borderBottom: '1px solid #eee' }}>Harga</th>
              <th style={{ padding: 8, borderBottom: '1px solid #eee' }}>Qty</th>
              <th style={{ padding: 8, borderBottom: '1px solid #eee' }}>Subtotal</th>
            </tr>
          </thead>
          <tbody>
            {cartItems.map(item => (
              <tr key={item.productId}>
                <td style={{ padding: 8, display: 'flex', alignItems: 'center', gap: 12 }}>
                  <img src={item.image} alt={item.name} style={{ width: 60, borderRadius: 8 }} />
                  <span>{item.name}</span>
                </td>
                <td style={{ padding: 8 }}>Rp {item.new_price.toLocaleString()}</td>
                <td style={{ padding: 8 }}>{item.qty}</td>
                <td style={{ padding: 8 }}>Rp {(item.new_price * item.qty).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <div style={{ textAlign: 'right', fontWeight: 'bold', fontSize: 18, marginBottom: 24 }}>
        Total: Rp {total.toLocaleString()}
      </div>
      <button className="shop-hero-btn" style={{ float: 'right' }} onClick={() => alert('Checkout berhasil!')}>Checkout</button>
    </div>
  );
}

export default Cart;
